CREATE TABLE ibexa_content_relation (id INT AUTO_INCREMENT NOT NULL, content_type_field_definition_id INT DEFAULT 0 NOT NULL, from_contentobject_id INT DEFAULT 0 NOT NULL, from_contentobject_version INT DEFAULT 0 NOT NULL, relation_type INT DEFAULT 1 NOT NULL, to_contentobject_id INT DEFAULT 0 NOT NULL, INDEX ibexa_content_relation_to_co_id (to_contentobject_id), INDEX ibexa_content_relation_from (from_contentobject_id, from_contentobject_version, content_type_field_definition_id), INDEX ibexa_content_relation_ccfd_id (content_type_field_definition_id), PRIMARY KEY(id)) DEFAULT CHARACTER SET utf8 COLLATE `utf8_unicode_ci` ENGINE = InnoDB;
